import { bindVueRuntime } from 'hel-micro'
import * as Vue from 'vue'
import { loadPanelLib, loadPickerLib, loadRemoteLib } from './configs/remote'

/*
|--------------------------------------------------------------------------
|
| 把宿主 vue 运行时挂到 window.Vue，远程组件（external 了 vue）会复用这一份
| 必须在远程组件脚本加载之前执行，否则会出现两份 vue 导致响应式失效
|
|--------------------------------------------------------------------------
*/
bindVueRuntime({ Vue })

;(async function () {
  try {
    // 三个远程包都属于宿主启动依赖，严格串行加载并校验关键导出，
    // 避免多个 Hel 包同时注册时出现时序竞态或空代理对象。
    const panel = await loadPanelLib()
    if (!panel?.PropsPlayground) {
      throw new Error('libs-vue3-leva 未导出 PropsPlayground')
    }

    const remote = await loadRemoteLib()
    if (!remote?.HelloWorld) {
      throw new Error('comps-vue3 未导出 HelloWorld')
    }

    const picker = await loadPickerLib()
    if (!picker?.CategoryPicker) {
      throw new Error('comps-vue3-picker 未导出 CategoryPicker')
    }

    // 所有公共远程依赖成功后才挂载宿主。
    void remote
    void picker
    await import('./loadApp')
  } catch (error) {
    console.error('[demo-vue3] 启动依赖加载失败:', error)
  }
})()
