import { preFetchLib } from 'hel-micro'

export type HelLibRecord = Record<string, unknown>

export type HelLoadSpec<T extends HelLibRecord = HelLibRecord> = {
  name: string
  host: string
  platform?: string
  appGroupName?: string
  requiredExports?: string[]
  custom?: Record<string, unknown>
} & { __type?: T }

export type HelLoadPhase = 'meta' | 'assets' | 'ready' | 'exports'

export class HelLoadError extends Error {
  readonly moduleName: string
  readonly host: string
  readonly phase: HelLoadPhase
  readonly missingExports: string[]
  readonly cause: unknown

  constructor(options: {
    moduleName: string
    host: string
    phase: HelLoadPhase
    message: string
    missingExports?: string[]
    cause?: unknown
  }) {
    super(options.message, { cause: options.cause })
    this.name = 'HelLoadError'
    this.moduleName = options.moduleName
    this.host = options.host
    this.phase = options.phase
    this.missingExports = options.missingExports || []
    this.cause = options.cause
  }
}

export function isHelMetaHost(host: string) {
  return host.trim().toLowerCase().endsWith('hel-meta.json')
}

export function assertHelExports<T extends HelLibRecord>(
  moduleName: string,
  host: string,
  lib: T | null | undefined,
  requiredExports: string[] = [],
): asserts lib is T {
  if (!lib) {
    throw new HelLoadError({
      moduleName,
      host,
      phase: 'ready',
      message: '[hel-loader] ' + moduleName + ' 未返回远程模块对象',
    })
  }

  const missingExports = requiredExports.filter((name) => !(name in lib))
  if (missingExports.length) {
    throw new HelLoadError({
      moduleName,
      host,
      phase: 'exports',
      missingExports,
      message: '[hel-loader] ' + moduleName + ' 缺少导出：' + missingExports.join(', '),
    })
  }
}

export async function loadHelLib<T extends HelLibRecord = HelLibRecord>(
  spec: HelLoadSpec<T>,
): Promise<T> {
  const { name, host, platform, appGroupName, requiredExports = [], custom = {} } = spec
  try {
    const lib = await preFetchLib<T>(name, {
      ...(platform ? { platform } : {}),
      custom: {
        host,
        ...(appGroupName ? { appGroupName } : {}),
        skipFetchHelMeta: !isHelMetaHost(host),
        enable: true,
        trust: true,
        ...custom,
      },
    })
    assertHelExports(name, host, lib, requiredExports)
    return lib
  } catch (error) {
    if (error instanceof HelLoadError) throw error
    throw new HelLoadError({
      moduleName: name,
      host,
      phase: 'assets',
      message:
        '[hel-loader] ' +
        name +
        ' 加载失败：' +
        (error instanceof Error ? error.message : String(error)),
      cause: error,
    })
  }
}

export async function loadHelLibsSerial(
  specs: HelLoadSpec[],
): Promise<HelLibRecord[]> {
  const loaded: HelLibRecord[] = []
  for (const spec of specs) {
    // 顺序是有意的：hel-micro custom 模式下并发注册可能互相覆盖。
    loaded.push(await loadHelLib(spec))
  }
  return loaded
}

export function resolveHelHost(options: {
  packageName: string
  target: 'unpkg' | 'github' | 'sftp'
  version?: string
  baseUrl?: string
  projectName?: string
}) {
  const { packageName, target, version = '', projectName, baseUrl = '' } = options
  const ref =
    version && version.toLowerCase() !== 'latest'
      ? packageName + '@' + version
      : packageName
  if (target === 'unpkg') {
    return 'https://unpkg.com/' + ref + '/hel_dist/hel-meta.json'
  }
  if (!baseUrl) throw new Error('[hel-loader] ' + target + ' 需要 baseUrl')
  const base = baseUrl.replace(/\/+$/, '')
  const pathName = projectName || packageName.split('/').pop() || packageName
  return base + '/' + pathName + '/hel_dist/hel-meta.json'
}

