/*
|--------------------------------------------------------------------------
|
| 远程组件（comps-vue3）的加载参数
|
|--------------------------------------------------------------------------
*/
import { loadHelLib } from '@melt-js/libs-core'
import { defineAsyncComponent } from 'vue'
import type { Component } from 'vue'

/** 远程组件 hel 组名，对应 comps-vue3 的 appGroupName / LIB_NAME */
export const REMOTE_LIB_NAME = 'comps-vue3'

/** comps-vue3 对外暴露的组件集合 */
export type RemoteComps = {
  HelloWorld: Component
  CircularMenu: Component
  MagneticButton: Component
  SpotlightButton: Component
  GlowBorder: Component
  Typewriter: Component
  TiltCard: Component
  FloatingLabelInput: Component
  PasswordInput: Component
  ExpandSearch: Component
  CyberInput: Component
  CorgiInput: Component
  GridLoading: Component
  GooeyBallsLoading: Component
  DnaLoading: Component
  NeonRingLoading: Component
  GearLoading: Component
  VortexLoading: Component
  WaterBallLoading: Component
  HourglassLoading: Component
  CubeWaveLoading: Component
  JellyLoading: Component
  DominoLoading: Component
  SlideAuthPanel: Component
  TerminalAuth: Component
  WheelMenuButton: Component
  PhotoSphere: Component
  WarpStarfield: Component
  ChinaRouteMap: Component
  SplitCodePreview: Component
  BookFlip: Component
  MinecraftChest: Component
  FilmRoll: Component
  RopeGallery: Component
  CompareSlider: Component
  PosterCollage: Component
  LiftCard: Component
  BilibiliBanner: Component
}

export type PickerComps = {
  CategoryPicker: Component
  RegionGroupPicker: Component
}

const isProd = import.meta.env.PROD

/** 本地联调地址：comps-vue3 的 dev 端口（全局规则见仓库根目录 ports.json，comps = 200xx） */
export const LOCAL_HOST = 'http://localhost:20020'

/** 线上地址：unpkg 上 comps-vue3 的 hel-meta.json */
export const UNPKG_HOST = 'https://unpkg.com/@melt-js/comps-vue3/hel_dist/hel-meta.json'

export const PICKER_LIB_NAME = 'comps-vue3-picker'
const PICKER_LOCAL_HOST = 'http://localhost:20097'
const PICKER_UNPKG_HOST = 'https://unpkg.com/@melt-js/comps-vue3-picker/hel_dist/hel-meta.json'
const pickerHost =
  (import.meta.env.VITE_PICKER_HOST as string | undefined) ||
  (isProd ? PICKER_UNPKG_HOST : PICKER_LOCAL_HOST)

/**
 * 远程组件地址
 * - 生产构建（vite build）：unpkg 上的 hel-meta.json，发布后的 demo 直接加载线上组件
 * - 本地开发（vite dev）：localhost:20020
 * - 可用 VITE_REMOTE_HOST 覆盖
 */
const host =
  (import.meta.env.VITE_REMOTE_HOST as string | undefined) || (isProd ? UNPKG_HOST : LOCAL_HOST)

/**
 * 入口处预加载远程组件（与 demo-vue2-ele 一致），重复调用复用同一个 Promise。
 * host 以 hel-meta.json 结尾时直接取元数据；本地 dev server 没有该文件，改为解析 index.html。
 */
let remoteLibPromise: Promise<RemoteComps> | undefined
let pickerLibPromise: Promise<PickerComps> | undefined

export function loadRemoteLib(): Promise<RemoteComps> {
  if (!remoteLibPromise) {
    remoteLibPromise = loadHelLib<RemoteComps>({
      name: REMOTE_LIB_NAME,
      host,
      requiredExports: ['HelloWorld'],
    })
  }
  return remoteLibPromise!
}

/**
 * 把远程组件包成异步组件：入口处已经 preFetchLib 过，loader 里只是取一下组件本身，
 * 各示例页因此不用重复写 defineAsyncComponent 的样板。
 */
export function remoteComponent(name: keyof RemoteComps, timeout = 10000) {
  return defineAsyncComponent({
    loader: async () => (await loadRemoteLib())[name],
    timeout,
  })
}

export function loadPickerLib(): Promise<PickerComps> {
  if (!pickerLibPromise) {
    if (!isProd) {
      pickerLibPromise = import('../../../comps-vue3-picker/src/components').then((module) => module.default as PickerComps)
    } else {
      pickerLibPromise = loadHelLib<PickerComps>({
        name: PICKER_LIB_NAME,
        host: pickerHost,
        platform: 'picker',
        appGroupName: PICKER_LIB_NAME,
        requiredExports: ['CategoryPicker'],
      })
    }
  }
  return pickerLibPromise!
}

/* -------------------------------------------------------------------------- */
/*  属性面板远程包（Vue 3 版 libs-vue3-leva）                                      */
/* -------------------------------------------------------------------------- */

/** 面板远程包的 hel 组名 */
export const PANEL_LIB_NAME = 'libs-vue3-leva'

/** 面板远程包对外暴露的组件集合 */
export type RemotePanel = {
  PropsPanel: Component
  PropsPlayground: Component
}

/** 本地联调地址：libs-vue3-leva 的 dev 端口（libs = 100xx） */
const PANEL_LOCAL_HOST = 'http://localhost:10040'

/** 线上地址：unpkg 上 libs-vue3-leva 的 hel-meta.json */
const PANEL_UNPKG_HOST = 'https://unpkg.com/@melt-js/libs-vue3-leva/hel_dist/hel-meta.json'

const panelHost =
  (import.meta.env.VITE_PANEL_HOST as string | undefined) ||
  (isProd ? PANEL_UNPKG_HOST : PANEL_LOCAL_HOST)

let panelLibPromise: Promise<RemotePanel> | undefined

export function loadPanelLib(): Promise<RemotePanel> {
  if (!panelLibPromise) {
    panelLibPromise = loadHelLib<RemotePanel>({
      name: PANEL_LIB_NAME,
      host: panelHost,
      requiredExports: ['PropsPlayground'],
    })
  }
  return panelLibPromise!
}
